import { API_BASE_URL } from './config.js';

// 取得目前選擇帳號資訊（含 simulation_date）
async function getCurrentAccount() {
	try {
		const res = await fetch(`${API_BASE_URL}/current-account`, { credentials: 'include' });
		if (!res.ok) return null;
		const data = await res.json();
		if (!data.ok) return null;
		return data.account;
	} catch (e) {
		return null;
	}
}

async function fetchTradeHistory(accountId, tradeDate, accountType) {
	if (!accountId || !tradeDate) return [];
	let url = '';
	if (accountType === 'history') {
		url = `${API_BASE_URL}/trade_history/history?account_id=${accountId}&trade_date=${tradeDate}`;
	} else {
		url = `${API_BASE_URL}/trade_history/realtime?account_id=${accountId}&trade_date=${tradeDate}`;
	}
	try {
		const res = await fetch(url);
		if (!res.ok) throw new Error('API 請求失敗');
		const data = await res.json();
		if (data.error) throw new Error(data.error);
		return data;
	} catch (err) {
		alert('查詢失敗: ' + err.message);
		return [];
	}
}

function renderTradeHistory(data, accountType) {
	const table = document.querySelector('.table.table-bordered');
	const thead = table.querySelector('thead tr');
	const tbody = table.querySelector('tbody');
	tbody.innerHTML = '';
	// 動態產生表頭
	thead.innerHTML = '';
	if (accountType === 'history') {
		[
			'股票代碼', '股票名稱', '整股零股', '交易類型', '下單日期', '是否成交'
		].forEach(h => {
			const th = document.createElement('th');
			th.textContent = h;
			thead.appendChild(th);
		});
		data.forEach(row => {
			const tr = document.createElement('tr');
			tr.innerHTML = `
				<td>${row['股票代碼']}</td>
				<td>${row['股票名稱']}</td>
				<td>${row['整股零股']}</td>
				<td>${row['交易類型']}</td>
				<td>${row['下單日期']}</td>
				<td>${row['是否成交']}</td>
			`;
			tbody.appendChild(tr);
		});
	} else {
		[
			'股票代碼', '股票名稱', '整股零股', '交易類型', '成交價', '張數', '手續費', '證交稅', '借券費', '收付金額', '時間'
		].forEach(h => {
			const th = document.createElement('th');
			th.textContent = h;
			thead.appendChild(th);
		});
		data.forEach(row => {
			const tr = document.createElement('tr');
			tr.innerHTML = `
				<td>${row['股票代碼']}</td>
				<td>${row['股票名稱']}</td>
				<td>${row['整股零股']}</td>
				<td>${row['交易類型']}</td>
				<td>${row['成交價']}</td>
				<td>${row['張數']}</td>
				<td>${row['手續費']}</td>
				<td>${row['證交稅']}</td>
				<td>${row['借券費']}</td>
				<td>${row['收付金額']}</td>
				<td>${row['時間']}</td>
			`;
			tbody.appendChild(tr);
		});
	}
}

window.addEventListener('DOMContentLoaded', async () => {
    console.log('DOMContentLoaded fired');
    const account = await getCurrentAccount();
    console.log('account:', account);
    if (!account) {
        console.log('No account, return');
        return;
    }
    const accountId = account.selected_account_id || account.saccount_id || account.id;
    const accountType = account.selected_account_type || account.account_type || account.type;
    const simDateRaw = account.selected_account_simulation_date || account.simulation_date;
    console.log('accountId:', accountId, 'accountType:', accountType, 'simDateRaw:', simDateRaw);
    if (!simDateRaw) {
        console.log('No simDateRaw, return');
        return;
    }
    const tradeDateObj = new Date(simDateRaw);
    const tradeDate = isNaN(tradeDateObj) ? simDateRaw : tradeDateObj.toISOString().slice(0, 10);
    console.log('tradeDate:', tradeDate);
    const data = await fetchTradeHistory(accountId, tradeDate, accountType);
    console.log('tradeHistory data:', data);
    renderTradeHistory(data, accountType);
});

